def logged(fn=None):
  def inner(*args):
    return ("logged", fn(*args) if fn else None)
  return inner
def repeat(times: int = 2):
  def deco(fn):
    def inner(*args):
      return [fn(*args) for _ in range(times)]
    return inner
  return deco
@logged
def add(a: int = 1, b: int = 2) -> int:
  return a + b
@repeat(2)
def hi():
  return "hi"
def decorated():
  return [add(1, 2), hi()]
close(None)

